import React, { useEffect, useState } from "react";
import axios from "axios";
import { Grid, Card, Typography, Modal } from "@mui/material";
import DefaultProjectCard from "examples/Cards/ProjectCards/DefaultProjectCard";
import { useNavigate, Routes, Route } from "react-router-dom";
import ClientDashboardLayout from "examples/LayoutContainers/DashboardLayout/client_dashboard_layout";
import DashboardNavbar from "examples/Navbars/DashboardNavbar";
import land4sale from "assets/images/land4sale.webp";
import LandListedDetails from "../land_listed_details.js";
import { useCookies } from "react-cookie";
import MDAlert from "components/MDAlert";
import MDBox from "components/MDBox/index.js";
import MDInput from "components/MDInput/index.js";
import MDTypography from "components/MDTypography/index.js";

import swal from "sweetalert";
import MDButton from "components/MDButton/index.js";

function MyListedLands() {
  const [projects, setProjects] = useState([]);
  const [cookies, setCookie, removeCookie] = useCookies(["user_id"]);
  const baseUrl = process.env.REACT_APP_BACKEND_BASE_URL;
  const user_id = cookies.user_id;
  const [price, setPrice] = useState(9500);
  const [land_id, setLand_id] = useState("");
  const [message, setMessage] = useState("Lodinng...");

  const handleUnListClick = async () => {
    console.log(`here are the data : ${land_id},=== price : ${price}, `);
    await axios
      .put(`${baseUrl}/web5/land_layouts/index.php`, null, {
        params: { land_code: land_id, price: price, land_status: 0 },
      })
      .then((response) => {
        // Handle success, e.g., update state or show a success message
        console.log(response.data);

        swal("Great Job !! you  Un listed Land", land_id, "success");
      })
      .catch((error) => {
        console.error("Error uploading file", error);
        swal("Failed to list Land", error.toString(), "error");
        // Handle error, e.g., show an error message to the user
      });
  };

  useEffect(() => {
    console.log(`prince here is your iser id : ${user_id}`);
    const fetchProjects = async () => {
      try {
        const response = await axios.get(`${baseUrl}/web5/my_listed_lands/`, {
          params: {
            user_id,
          },
        });
        if (response.data < 1) {
          setMessage("You dont have Lands");
        } else {
          console.log(`prince here ,`, response.data);
          setProjects(response.data);
        }
      } catch (error) {
        console.error("Failed to fetch projects:", error);
      }
    };

    fetchProjects();
  }, []);

  return (
    <ClientDashboardLayout>
      <DashboardNavbar />
      <MDBox p={3}>
        <Typography variant="h4" align="center" gutterBottom>
          My Listed Land
        </Typography>
        <Grid container spacing={6} p={2}>
          <Grid container spacing={3}>
            {projects.map((land, index) => (
              <Grid item xs={12} sm={6} md={4} key={index}>
                <Card>
                  <img src={land4sale} />

                  <MDBox p={2} textAlign="left">
                    <MDTypography variant="h6" color="text.primary">
                      {land.description}
                    </MDTypography>
                    <MDTypography variant="body2" color="text.secondary">
                      CODE : {land.land_id.toUpperCase()}
                    </MDTypography>
                    <MDTypography variant="body2" color="text.secondary">
                      TYPE: {land.type.toUpperCase()}
                    </MDTypography>
                    <MDTypography variant="body2" color="text.secondary">
                      SIZE : {land.size.toUpperCase()} HA
                    </MDTypography>

                    <MDButton
                      variant="contained"
                      color="info"
                      fullWidth
                      onClick={async () => {
                        setPrice(land.price.toString());
                        setLand_id(land.land_id.toString());
                        await handleUnListClick(land.land_id, land.price);
                      }}
                    >
                      Un List
                    </MDButton>
                  </MDBox>
                </Card>
              </Grid>
            ))}
          </Grid>
        </Grid>
      </MDBox>
    </ClientDashboardLayout>
  );
}

export default MyListedLands;
