import React, { useState, useEffect } from "react";
import axios from "axios";
import DataTable from "examples/Tables/DataTable";
import MDButton from "components/MDButton";
import swal from "sweetalert";
import { useCookies } from "react-cookie";
import CircularProgress from "@mui/material/CircularProgress";
import Box from "@mui/material/Box";

const BuyApplicationDataTable = () => {
  const [isLoading, setIsLoading] = useState(true); // For initial data fetch
  const [isActionLoading, setIsActionLoading] = useState(false); // For actions like Get Title Deed
  const baseUrl = process.env.REACT_APP_BACKEND_BASE_URL;
  const [cookies] = useCookies(["user_id"]);
  const user_id = cookies.user_id;
  const [data, setData] = useState([]);

  // Fetch applications
  const fetchApplications = async () => {
    setIsLoading(true); // Start loading animation
    try {
      const response = await axios.get(`${baseUrl}/web5/my_applications/`, {
        params: { user_id },
      });
      console.log("Fetched Data:", response.data);
      setData(response.data || []);
    } catch (error) {
      console.error("Error fetching applications:", error);
      swal("Error", "Failed to fetch applications", "error");
    }
    setIsLoading(false); // Stop loading animation
  };

  useEffect(() => {
    fetchApplications();
  }, []); // Fetch only once on mount

  // Handle title deed action
  const handleAction = async (applicationNumber) => {
    setIsActionLoading(true); // Start loading animation for action
    console.log(`Processing Title Deed for Application ID: ${applicationNumber}`);

    try {
      const response = await axios.get(`${baseUrl}/web5/blockchain_title_deed/index.php?application_id=${applicationNumber}`, {
        params: { application_id: applicationNumber },
      });

      console.log("Blockchain Title Deed Response:", response.data);
      if (response.data.status === "success") {
        swal("Success", response.data.message, "success");
        fetchApplications(); // Refresh the table
      } else {
        swal("Error", response.data.message, "error");
      }
    } catch (error) {
      console.error("Error processing Title Deed:", error);
      swal("Error", "Failed to process Title Deed", "error");
    }

    setIsActionLoading(false); // Stop loading animation for the action
  };

  // Display loading spinner while data is being fetched
  if (isLoading) {
    return (
      <Box display="flex" justifyContent="center" alignItems="center" height="100vh">
        <CircularProgress />
      </Box>
    );
  }

  return (
    <DataTable
      table={{
        columns: [
          { Header: "Application ID", accessor: "application_id" },
          { Header: "Land ID", accessor: "application_land_id" },
          { Header: "Price (MK)", accessor: "price" },
          { Header: "Size (sq.m)", accessor: "size" },
          {
            Header: "Layout",
            accessor: "layout",
            Cell: ({ value }) =>
              value ? (
                <MDButton variant="gradient" onClick={() => window.open(value, "_blank")}>
                  View
                </MDButton>
              ) : (
                "N/A"
              ),
          },
          {
            Header: "Status",
            accessor: "action",
            Cell: ({ value }) => (<><MDButton
                  variant="gradient"
                  color="info"
                  onClick={() => handleAction(value)}
                  disabled={isActionLoading}
                >
                  {isActionLoading ? "Processing..." : "Get Title Deed"}
                </MDButton></>),
          },
        ],
        rows: data.map((item) => ({
          application_id: item.appliction_number,
          application_land_id: item.land_id || "N/A",
          price: item.price || "N/A",
          size: item.size || "N/A",
          layout: item.layout || "N/A",
          action:item.appliction_number,
        })),
      }}
    />
  );
};

export default BuyApplicationDataTable;
