// ListPopup.js
import React, { useState, useEffect } from "react";
import { Modal, Grid, MenuItem, Autocomplete, TextField } from "@mui/material";
import Card from "@mui/material/Card";
import MDInput from "components/MDInput";
import MDButton from "components/MDButton";
import MDBox from "components/MDBox";
import MDTypography from "components/MDTypography";
import axios from "axios";
import swal from "sweetalert";

const ListPopup = ({ open, onClose }) => {
  const [landCode, setLandCode] = useState("");
  const [price, setPrice] = useState("");
  const [district, setDistrict] = useState("");
  const [area, setArea] = useState("");
  const [lands, setLands] = useState([]);
  const [filteredLands, setFilteredLands] = useState([]);

  const baseUrl = process.env.REACT_APP_BACKEND_BASE_URL;

  const districtsWithAreas = {
    Mzimba: ["Ekwendeni", "Mzalangwe", "Manyamula"],
    Lilongwe: ["City Centre", "Area 25", "Kawale"],
    Blantyre: ["Ndirande", "Chilomoni", "Machinjiri"],
    // Add additional districts and their areas as needed
  };

  // Fetch all lands on component mount
  useEffect(() => {
    const fetchLands = async () => {
      try {
        const response = await axios.get(`${baseUrl}/web5/land_layouts`);
        setLands(response.data);
      } catch (error) {
        console.error("Error fetching lands:", error);
      }
    };
    fetchLands();
  }, []);

  // Update filtered lands based on search input
  useEffect(() => {
    let updatedLands = lands;

    // Filter by district
    if (district) {
      updatedLands = updatedLands.filter((land) =>
        land.land_id.startsWith(district.slice(0, 2).toUpperCase())
      );
    }

    // Filter by area
    if (area) {
      updatedLands = updatedLands.filter((land) =>
        land.description.includes(area)
      );
    }

    // Filter by land code input
    if (landCode) {
      updatedLands = updatedLands.filter((land) =>
        land.land_id.toLowerCase().includes(landCode.toLowerCase())
      );
    }

    setFilteredLands(updatedLands);
  }, [district, area, landCode, lands]);

  const handleLandCodeSelect = (code) => {
    setLandCode(code);
  };

  const handlePriceChange = (e) => {
    setPrice(e.target.value);
  };

  const handleDistrictChange = (e) => {
    setDistrict(e.target.value);
    setArea(""); // Reset area when district changes
  };

  const handleAreaChange = (e) => {
    setArea(e.target.value);
  };

  const handleCancel = () => {
    onClose();
  };

  const handleMints = () => {
    axios
      .put(`${baseUrl}/web5/land_layouts/index.php`, null, {
        params: { land_code: landCode, land_status: 2, price: price },
      })
      .then((response) => {
        console.log(response.data);
        onClose();
        swal("Great Job !! Requested to Buy", landCode.toString(), "success");
      })
      .catch((error) => {
        console.error("Error uploading file", error);
        swal("Failed to list Land", error.toString(), "error");
      });
  };

  return (
    <Modal open={open} onClose={onClose}>
      <Grid
        container
        justifyContent="center"
        style={{ height: "100vh", alignItems: "center" }}
      >
        <Grid item xs={22} sm={10} md={8} lg={6} xl={4}>
          <Card>
            <MDBox
              variant="gradient"
              bgColor="info"
              borderRadius="lg"
              coloredShadow="success"
              mx={2}
              mt={-3}
              p={3}
              mb={1}
              textAlign="center"
            >
              <MDTypography
                variant="h4"
                fontWeight="medium"
                color="white"
                mt={1}
              >
                List Lands
              </MDTypography>
              <MDTypography
                display="block"
                variant="button"
                color="white"
                my={1}
              >
                Land Details
              </MDTypography>
            </MDBox>
            <MDBox pt={4} pb={3} px={3}>
              <form>
                <Grid container spacing={2}>
                  <Grid item xs={12}>
                    <MDBox mb={2}>
                      <Autocomplete
                        options={filteredLands}
                        getOptionLabel={(land) => land.land_id}
                        onChange={(event, newValue) => {
                          if (newValue) handleLandCodeSelect(newValue.land_id);
                        }}
                        renderInput={(params) => (
                          <TextField
                            {...params}
                            label="Search Land Code"
                            variant="standard"
                            value={landCode}
                            onChange={(e) => setLandCode(e.target.value)}
                            fullWidth
                          />
                        )}
                      />
                    </MDBox>
                  </Grid>
                  <Grid item xs={6}>
                    <MDBox mb={2}>
                      <MDInput
                        select
                        label="District"
                        value={district}
                        onChange={handleDistrictChange}
                        fullWidth
                        variant="standard"
                      >
                        {Object.keys(districtsWithAreas).map((dist) => (
                          <MenuItem key={dist} value={dist}>
                            {dist}
                          </MenuItem>
                        ))}
                      </MDInput>
                    </MDBox>
                  </Grid>
                  <Grid item xs={6}>
                    <MDBox mb={2}>
                      <MDInput
                        select
                        label="Area"
                        value={area}
                        onChange={handleAreaChange}
                        fullWidth
                        variant="standard"
                        disabled={!district}
                      >
                        {district &&
                          districtsWithAreas[district].map((areaOption) => (
                            <MenuItem key={areaOption} value={areaOption}>
                              {areaOption}
                            </MenuItem>
                          ))}
                      </MDInput>
                    </MDBox>
                  </Grid>
                  <Grid item xs={12}>
                    <MDBox mb={2}>
                      <MDInput
                        type="text"
                        label="Price"
                        variant="standard"
                        value={price}
                        onChange={handlePriceChange}
                        fullWidth
                      />
                    </MDBox>
                  </Grid>
                  <Grid container spacing={2}>
                    <Grid item xs={6}>
                      <MDBox mb={2}>
                        <MDButton
                          variant="gradient"
                          color="info"
                          onClick={handleMints}
                          fullWidth
                        >
                          List
                        </MDButton>
                      </MDBox>
                    </Grid>
                    <Grid item xs={6}>
                      <MDBox mb={2}>
                        <MDButton
                          variant="gradient"
                          color="warning"
                          onClick={handleCancel}
                          fullWidth
                        >
                          Cancel
                        </MDButton>
                      </MDBox>
                    </Grid>
                  </Grid>
                </Grid>
              </form>
            </MDBox>
          </Card>
        </Grid>
      </Grid>
    </Modal>
  );
};

export default ListPopup;
