import React, { useEffect, useState } from "react";
import axios from "axios";
import { Grid, Card, Typography, Modal, MenuItem, Select } from "@mui/material";
import DefaultProjectCard from "examples/Cards/ProjectCards/DefaultProjectCard";
import { Routes, Route } from "react-router-dom";
import ClientDashboardLayout from "examples/LayoutContainers/DashboardLayout/client_dashboard_layout";
import DashboardNavbar from "examples/Navbars/DashboardNavbar";
import land4sale from "assets/images/land4sale.webp";
import LandListedDetails from "./land_listed_details.js";
import { useCookies } from "react-cookie";

import MDBox from "components/MDBox";
import MDInput from "components/MDInput";
import MDTypography from "components/MDTypography";
import swal from "sweetalert";
import MDButton from "components/MDButton";
import "react-phone-number-input/style.css";
import PhoneInput from "react-phone-number-input";
import { stringify } from "stylis";

function Basicp() {
  const [lands, setLands] = useState([]);
  const [buyClicked, setBuyClicked] = useState(false);
  const [selectedLand, setSelectedLand] = useState(null);
  const [paymentMethod, setPaymentMethod] = useState("");
  const [cardNumber, setCardNumber] = useState("");
  const [cardExpiry, setCardExpiry] = useState("");
  const [mobileNumber, setMobileNumber] = useState("");
  const [cookies] = useCookies(["user_id"]);

  const baseUrl = process.env.REACT_APP_BACKEND_BASE_URL;
  const user_id = cookies.user_id;

  useEffect(() => {
    const fetchLands = async () => {
      try {
        const response = await axios.get(
          `${baseUrl}/web5/commercial_customary/`
        );
        setLands(response.data);
      } catch (error) {
        console.error("Failed to fetch lands:", error);
      }
    };
    fetchLands();
  }, []);

  const handleBuyClick = (land) => {
    setSelectedLand(land);
    setBuyClicked(true);
  };

  const handleCloseModal = () => {
    setSelectedLand(null);
    setBuyClicked(false);
  };

  const handlePurchase = async (event) => {
    event.preventDefault();
    console.log(`h=----------yes start purchasing------`);

    try {
      const applicationData = {
        land_code: selectedLand.land_id,
        user_id: user_id,
      };

      console.log("Application Data:", applicationData);

      const response = await axios.post(
        `${baseUrl}/web5/application/`,
        applicationData
      );
      console.log(`hr=ere land code : `, response.data);
      swal(
        "Purchase Successful",
        `You have purchased ${selectedLand.title}`,
        "success"
      );
      handleCloseModal();
    } catch (error) {
      console.error("Error processing payment", error);
      swal(
        "Purchase Failed",
        "Unable to complete the transaction. Please try again.",
        "error"
      );
    }
  };

  return (
    <ClientDashboardLayout>
      <DashboardNavbar />
      <Routes>
        <Route
          path="/tables/client/land_listed_details/:projectId"
          element={<LandListedDetails projectId={selectedLand?.id} />}
        />
      </Routes>

      <Grid container spacing={4} p={3}>
        {lands.length === 0 ? (
          <Typography variant="h5" color="textSecondary">
            No listed lands available.
          </Typography>
        ) : (
          lands.map((land) =>
            land.owner_id === user_id ? (
              <MDTypography>No Listed Lands</MDTypography>
            ) : (
              <Grid item xs={12} sm={6} md={4} lg={3} key={land.id}>
                <Card
                  sx={{
                    boxShadow: 5,
                    borderRadius: 2,
                    overflow: "hidden",
                    transition: "transform 0.3s ease-in-out",
                    "&:hover": {
                      transform: "scale(1.05)",
                    },
                  }}
                >
                  <img
                    src={land4sale}
                    alt="Land"
                    style={{ width: "100%", height: 100, objectFit: "cover" }}
                  />
                  <MDBox p={2}>
                    <Typography variant="h6">
                      Title: {land.full_name}
                    </Typography>
                    <Typography variant="body2" color="textSecondary">
                      {land.description}
                    </Typography>
                    <Typography variant="body2" mt={1}>
                      <strong>Price:</strong> MK{land.price}
                    </Typography>
                    <Typography variant="body2" color="textSecondary">
                      <strong>Size:</strong> {land.size} sq. meters
                    </Typography>
                    <Typography variant="body2" color="textSecondary">
                      <strong>Location:</strong> Mzuzu
                    </Typography>
                    <MDButton
                      variant="contained"
                      color="primary"
                      fullWidth
                      sx={{ mt: 2 }}
                      onClick={() => handleBuyClick(land)}
                    >
                      Buy Now
                    </MDButton>
                  </MDBox>
                </Card>
              </Grid>
            )
          )
        )}
      </Grid>

      {buyClicked && selectedLand && (
        <Modal open={buyClicked} onClose={handleCloseModal}>
          <Grid
            container
            justifyContent="center"
            alignItems="center"
            style={{ height: "100vh" }}
          >
            <Grid item xs={12} sm={10} md={8} lg={6} xl={4}>
              <Card>
                <MDBox pt={4} pb={3} px={3}>
                  <MDTypography
                    variant="h4"
                    fontWeight="medium"
                    color="red"
                    mt={1}
                  >
                    Checkout
                  </MDTypography>
                  <MDTypography
                    display="block"
                    variant="button"
                    color="red"
                    my={1}
                  >
                    Secure Land Purchase
                  </MDTypography>
                  <form>
                    <Grid container spacing={2}>
                      <Grid item xs={12}>
                        <MDInput
                          type="text"
                          label="Plot #"
                          value={selectedLand.land_id}
                          variant="standard"
                          fullWidth
                          disabled
                        />
                      </Grid>
                      <Grid item xs={12}>
                        <MDInput
                          type="text"
                          label="Price (MK)"
                          value={selectedLand.price}
                          variant="standard"
                          fullWidth
                          disabled
                        />
                      </Grid>
                      <Grid item xs={12}>
                        <Select
                          value={paymentMethod}
                          onChange={(e) => setPaymentMethod(e.target.value)}
                          displayEmpty
                          fullWidth
                          variant="standard"
                        >
                          <MenuItem value="" disabled>
                            Select Payment Method
                          </MenuItem>
                          <MenuItem value="visa">Visa</MenuItem>
                          <MenuItem value="mpamba">Mpamba</MenuItem>
                          <MenuItem value="airtel">Airtel Money</MenuItem>
                        </Select>
                      </Grid>

                      {paymentMethod === "visa" && (
                        <>
                          <Grid item xs={12}>
                            <MDInput
                              type="text"
                              label="Card Number"
                              value={cardNumber}
                              onChange={(e) => setCardNumber(e.target.value)}
                              variant="standard"
                              fullWidth
                            />
                          </Grid>
                          <Grid item xs={12}>
                            <MDInput
                              type="date"
                              label="Expiry Date (MM/YY)"
                              value={cardExpiry}
                              onChange={(e) => setCardExpiry(e.target.value)}
                              variant="standard"
                              fullWidth
                            />
                          </Grid>
                        </>
                      )}

                      {(paymentMethod === "mpamba" ||
                        paymentMethod === "airtel") && (
                        <Grid item xs={12}>
                          <PhoneInput
                            placeholder="Enter phone number"
                            value={mobileNumber}
                            onChange={setMobileNumber}
                            defaultCountry="MW"
                            fullWidth
                          />
                        </Grid>
                      )}
                    </Grid>

                    <Grid container spacing={2} mt={3}>
                      <Grid item xs={6}>
                        <MDButton
                          variant="contained"
                          color="success"
                          fullWidth
                          onClick={handlePurchase}
                        >
                          Confirm Purchase
                        </MDButton>
                      </Grid>
                      <Grid item xs={6}>
                        <MDButton
                          variant="contained"
                          color="error"
                          fullWidth
                          onClick={handleCloseModal}
                        >
                          Cancel
                        </MDButton>
                      </Grid>
                    </Grid>
                  </form>
                </MDBox>
              </Card>
            </Grid>
          </Grid>
        </Modal>
      )}
    </ClientDashboardLayout>
  );
}

export default Basicp;
