import React, { useState, useEffect } from "react";
import DataTable from "examples/Tables/DataTable";
import axios from "axios";
import MDButton from "components/MDButton";

const DynamicDataTable = () => {
  const [data, setData] = useState([]);
  const [isLoading, setIsLoading] = useState(true);
  const baseUrl = process.env.REACT_APP_BACKEND_BASE_URL;
  const handleLayoutClick = (landUrl) => {
    const win = window.open(landUrl, "_blank");
    win.focus();
  };

  useEffect(() => {
    const fetchData = async () => {
      console.log(`url is : ${baseUrl}`);
      try {
        const response = await axios.get(
          `${baseUrl}/web5/land_layouts/index.php`
        );
        console.log(`here all lands : `, response.data);
        setData(response.data);
        setIsLoading(false);
      } catch (error) {
        console.error("Error fetching data: ", error);
        setIsLoading(false);
      }
    };

    fetchData();
  }, [baseUrl]);

  if (isLoading) {
    return <div>Loading...</div>;
  }

  return (
    <DataTable
      table={{
        columns: [
          { Header: "Land ID", accessor: "land_id" },
          { Header: "Description", accessor: "description" },

          { Header: "Size (ha)", accessor: "size" },
          {
            Header: "Layout",
            accessor: "layout",
            Cell: ({ value }) => (
              <MDButton onClick={() => handleLayoutClick(value)}>
                View Map
              </MDButton>
            ),
          },
          { Header: "Price", accessor: "price" },
          { Header: "Land Status", accessor: "land_status" },
        ],
        rows: data.map((item) => ({
          land_status:
            item.land_status.toString() == "0" ? "new Land" : "On Sale",
          land_id: item.land_id,
          description: item.description,
          type: item.type,
          size: item.size,
          layout: item.layout,
          price: item.price,
        })),
      }}
    />
  );
};

export default DynamicDataTable;
