import React, { useState, useEffect } from "react";
import DataTable from "examples/Tables/DataTable";
import axios from "axios";
import { Button } from "react-bootstrap";
import swal from "sweetalert";
import MDButton from "components/MDButton";
const DynamicDataTable = () => {
  const [data, setData] = useState([]);
  const [price, setPrice] = useState("9500");
  const [isLoading, setIsLoading] = useState(true);
  const baseUrl = process.env.REACT_APP_BACKEND_BASE_URL;

  const handleLayoutClick = (landUrl) => {
    const win = window.open(landUrl, "_blank");
    win.focus();
  };

  useEffect(() => {
    console.log(`here stse`);
    const fetchData = async () => {
      try {
        const response = await axios.get(`${baseUrl}/web5/listed_lands`);
        console.log(`here is listed lands:`, response.data);
        if (response.data.length > 0) {
          setData(response.data);
        }

        setIsLoading(false);
      } catch (error) {
        console.error("Error fetching data: ", error);
        setIsLoading(false);
      }
    };

    fetchData();
  }, []);

  if (isLoading) {
    return <div>Loading...</div>;
  }

  const handleUnList = async (landCode) => {
    axios
      .put(`${baseUrl}/web5/land_layouts/index.php`, null, {
        params: { land_code: landCode, land_status: 0, price: price },
      })
      .then((response) => {
        console.log(response.data);

        swal("Great Job !! Requested to Buy", landCode.toString(), "success");
      })
      .catch((error) => {
        console.error("Error uploading file", error);
        swal("Failed to list Land", error.toString(), "error");
      });
  };
  return (
    <DataTable
      table={{
        columns: [
          ,
          { Header: "Land ID", accessor: "land_id" },
          { Header: "Description", accessor: "description" },

          { Header: "Size", accessor: "size" },
          {
            Header: "Layout",
            accessor: "layout",
            Cell: ({ value }) => (
              <MDButton onClick={() => handleLayoutClick(value)}>
                View Map
              </MDButton>
            ),
          },
          { Header: "Price", accessor: "price" },
          {
            Header: "Action",
            accessor: "id",
            Cell: ({ value }) => (
              <MDButton onClick={() => handleUnList(value)}>Un List</MDButton>
            ),
          },
        ],
        rows: data.map((item) => ({
          id: item.land_id,
          land_id: item.land_id,
          description: item.description,
          type: item.type,
          size: item.size,
          layout: item.layout,
          price: item.price,
        })),
      }}
    />
  );
};

export default DynamicDataTable;
