// ModalPopup.js
import React, { useState, useEffect } from "react";
import {
  Modal,
  Grid,
  Card,
  MenuItem,
  TextField,
  Button,
  Typography,
  Box,
} from "@mui/material";
import axios from "axios";
import swal from "sweetalert";
import MDButton from "components/MDButton";

const ModalPopup = ({ open, onClose }) => {
  const [description, setDescription] = useState("");
  const [landCode, setLandCode] = useState("");
  const [landloard, setLandloard] = useState("");
  const [type, setType] = useState("");
  const [size, setSize] = useState("");
  const [TRCoordinate, setTRCoordinate] = useState("");
  const [TLCoordinate, setTLCoordinate] = useState("");
  const [BRCoorinate, setBRCoordinate] = useState("");
  const [BLCoorinate, setBLCoordinate] = useState("");
  const [district, setDistrict] = useState("");
  const [area, setArea] = useState("");

  const baseUrl = process.env.REACT_APP_BACKEND_BASE_URL;

  const districtsWithAreas = {
    Mzimba: ["Ekwendeni", "Mzalangwe", "Manyamula"],
    Lilongwe: ["City Centre", "Area 25", "Kawale"],
    Blantyre: ["Ndirande", "Chilomoni", "Machinjiri"],
    // Add additional districts and their areas as needed
  };

  const landloardOptions = ["Lands", "MHC", "Other"];
  const landTypeOptions = ["Customary", "Commercial", "Other"];

  // Auto-generate land code based on district and area
  useEffect(() => {
    if (district && area) {
      generateLandCode(district, area);
    }
  }, [district, area]);

  const generateLandCode = async (selectedDistrict, selectedArea) => {
    try {
      const response = await axios.get(`${baseUrl}/web5/total_lands`);
      const totalLands = response.data[0]?.totalLands || 0;
      const districtCode = selectedDistrict.slice(0, 2).toUpperCase();
      const areaCode = selectedArea.slice(0, 2).toUpperCase();
      const newLandCode = `${districtCode}${areaCode}${totalLands + 1}`;
      setLandCode(newLandCode);
    } catch (error) {
      console.error("Error fetching total lands:", error);
    }
  };

  const handleCancel = () => {
    onClose();
  };

  const land_layout =
    "www.api.googlemaps.com/apiKey/" +
    TRCoordinate +
    TLCoordinate +
    BRCoorinate +
    BLCoorinate;
  const handleSubmit = async () => {
    const formData = new FormData();
    formData.append("land_id", landCode);
    formData.append("type", type);
    formData.append("size", size);
    formData.append("land_loard", landloard);
    formData.append("description", description);
    formData.append("land_layout", land_layout);
    formData.append("owner_id", "1")

    swal("Success!", `Registered Land Code: ${landCode}`, "success");

    try {
      await axios.post(`${baseUrl}/web5/land_layouts/index.php`, formData, {
        headers: { "Content-Type": "multipart/form-data" },
      });
      onClose();
    } catch (error) {
      console.error("Error submitting land data", error);
    }
  };

  return (
    <Modal open={open} onClose={onClose}>
      <Grid
        container
        justifyContent="center"
        style={{ height: "100vh", alignItems: "center" }}
      >
        <Grid item xs={12} sm={10} md={8} lg={6}>
          <Card>
            <Box
              variant="gradient"
              bgcolor="primary.main"
              p={3}
              textAlign="center"
            >
              <Typography variant="h5" color="white" fontWeight="medium">
                Land Registration
              </Typography>
              <Typography variant="body2" color="white" mt={1}>
                Please fill in the details to register a new land entry.
              </Typography>
            </Box>
            <Box p={3}>
              <form>
                <Grid container spacing={2}>
                  <Grid item xs={12}>
                    <TextField
                      label="Description"
                      fullWidth
                      variant="outlined"
                      value={description}
                      onChange={(e) => setDescription(e.target.value)}
                    />
                  </Grid>
                  <Grid item xs={12} sm={4}>
                    <TextField
                      label="District"
                      select
                      fullWidth
                      variant="outlined"
                      value={district}
                      onChange={(e) => {
                        setDistrict(e.target.value);
                        setArea(""); // Reset area when district changes
                      }}
                    >
                      {Object.keys(districtsWithAreas).map((dist) => (
                        <MenuItem key={dist} value={dist}>
                          {dist}
                        </MenuItem>
                      ))}
                    </TextField>
                  </Grid>
                  <Grid item xs={12} sm={4}>
                    <TextField
                      label="Area"
                      select
                      fullWidth
                      variant="outlined"
                      value={area}
                      onChange={(e) => setArea(e.target.value)}
                      disabled={!district} // Disable area selection until district is chosen
                    >
                      {district &&
                        districtsWithAreas[district].map((areaOption) => (
                          <MenuItem key={areaOption} value={areaOption}>
                            {areaOption}
                          </MenuItem>
                        ))}
                    </TextField>
                  </Grid>
                  <Grid item xs={12} sm={4}>
                    <TextField
                      label="Land Code"
                      fullWidth
                      variant="outlined"
                      value={landCode}
                      disabled
                    />
                  </Grid>
                  <Grid item xs={4}>
                    <TextField
                      label="Type"
                      select
                      fullWidth
                      variant="outlined"
                      value={type}
                      onChange={(e) => setType(e.target.value)}
                    >
                      {landTypeOptions.map((option) => (
                        <MenuItem key={option} value={option}>
                          {option}
                        </MenuItem>
                      ))}
                    </TextField>
                  </Grid>
                  <Grid item xs={4}>
                    <TextField
                      label="Landlord"
                      select
                      fullWidth
                      variant="outlined"
                      value={landloard}
                      onChange={(e) => setLandloard(e.target.value)}
                    >
                      {landloardOptions.map((option) => (
                        <MenuItem key={option} value={option}>
                          {option}
                        </MenuItem>
                      ))}
                    </TextField>
                  </Grid>
                  <Grid item xs={4}>
                    <TextField
                      label="Size (ha)"
                      fullWidth
                      variant="outlined"
                      type="number"
                      value={size}
                      onChange={(e) => setSize(e.target.value)}
                    />
                  </Grid>
                  <Grid item xs={6}>
                    <TextField
                      label="Top Left Coordinate"
                      fullWidth
                      variant="outlined"
                      value={TLCoordinate}
                      onChange={(e) => setTLCoordinate(e.target.value)}
                    />
                  </Grid>
                  <Grid item xs={6}>
                    <TextField
                      label="Top Right Coordinate"
                      fullWidth
                      variant="outlined"
                      value={TRCoordinate}
                      onChange={(e) => setTRCoordinate(e.target.value)}
                    />
                  </Grid>
                  <Grid item xs={6}>
                    <TextField
                      label="Bottom Left Coordinate"
                      fullWidth
                      variant="outlined"
                      value={BLCoorinate}
                      onChange={(e) => setBLCoordinate(e.target.value)}
                    />
                  </Grid>
                  <Grid item xs={6}>
                    <TextField
                      label="Bottom Right Coordinate"
                      fullWidth
                      variant="outlined"
                      value={BRCoorinate}
                      onChange={(e) => setBRCoordinate(e.target.value)}
                    />
                  </Grid>
                </Grid>
                <Grid container spacing={2} mt={3}>
                  <Grid item xs={6}>
                    <MDButton
                      color="success"
                      variant="gradient"
                      onClick={handleSubmit}
                      fullWidth
                    >
                      Register Land
                    </MDButton>
                  </Grid>
                  <Grid item xs={6}>
                    <MDButton
                      variant="contained"
                      color="warning"
                      onClick={handleCancel}
                      fullWidth
                    >
                      Cancel
                    </MDButton>
                  </Grid>
                </Grid>
              </form>
            </Box>
          </Card>
        </Grid>
      </Grid>
    </Modal>
  );
};

export default ModalPopup;
